#include <iostream>
#include <fstream>
#include <string>
#include <curl/curl.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

// Callback function to read data from the email body
size_t read_data_callback(void *ptr, size_t size, size_t nmemb, std::string *data) {
    if (data->empty()) {
        return 0;
    }

    size_t len = std::min(size * nmemb, data->size());
    memcpy(ptr, data->data(), len);
    data->erase(0, len);
    return len;
}

// Function to encrypt a string using AES-256-CBC
std::string encrypt(const std::string &plaintext, const std::string &key, const std::string &iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        throw std::runtime_error("Failed to create cipher context");
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()))) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Failed to initialize encryption");
    }

    int len;
    std::string ciphertext;
    ciphertext.resize(plaintext.size() + EVP_CIPHER_block_size(EVP_aes_256_cbc()));

    if (1 != EVP_EncryptUpdate(ctx, reinterpret_cast<unsigned char*>(&ciphertext[0]), &len, reinterpret_cast<const unsigned char*>(plaintext.c_str()), plaintext.size())) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Failed to encrypt data");
    }
    ciphertext.resize(len);

    if (1 != EVP_EncryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&ciphertext[0]) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Failed to finalize encryption");
    }
    ciphertext.resize(ciphertext.size() + len);

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext;
}

// Function to decrypt a string using AES-256-CBC
std::string decrypt(const std::string &ciphertext, const std::string &key, const std::string &iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        throw std::runtime_error("Failed to create cipher context");
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()))) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Failed to initialize decryption");
    }

    int len;
    std::string plaintext;
    plaintext.resize(ciphertext.size());

    if (1 != EVP_DecryptUpdate(ctx, reinterpret_cast<unsigned char*>(&plaintext[0]), &len, reinterpret_cast<const unsigned char*>(ciphertext.c_str()), ciphertext.size())) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Failed to decrypt data");
    }
    plaintext.resize(len);

    if (1 != EVP_DecryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&plaintext[0]) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Failed to finalize decryption");
    }
    plaintext.resize(plaintext.size() + len);

    EVP_CIPHER_CTX_free(ctx);
    return plaintext;
}

int main() {
    // Initialize libcurl
    CURL *curl = curl_easy_init();
    if (!curl) {
        std::cerr << "Error initializing libcurl." << std::endl;
        return 1;
    }

    // SMTP server details
    const std::string url = "smtp://smtp.gmail.com:587";
    const std::string username = "watchtower.test2023@gmail.com";
    std::string password; // To store the password

    // Read the encrypted password from the file "secret"
    std::ifstream secret_file("secret");
    if (!secret_file.is_open()) {
        std::cerr << "Error opening the 'secret' file." << std::endl;
        return 1;
    }

    std::string encrypted_password;
    getline(secret_file, encrypted_password);
    secret_file.close();

    // Decrypt the password
    const std::string key = "0123456789abcdef0123456789abcdef"; // 32-byte key for AES-256
    const std::string iv = "0123456789abcdef"; // 16-byte IV for AES-256
    try {
        password = decrypt(encrypted_password, key, iv);
    } catch (const std::exception &e) {
        std::cerr << "Error decrypting password: " << e.what() << std::endl;
        return 1;
    }

    const std::string mail_from = "watchtower.test2023@gmail.com";
    const std::string mail_rcpt = "spam.mhered@gmail.com";

    // Email content
    const std::string email_data =
        "From: Watchtower Tester <watchtower.test2023@gmail.com>\r\n"
        "To: SPAM <spam.mhered@gmail.com>\r\n"
        "Subject: Sending an email with CURL\r\n\r\n"
        "This is a pretty amazing email test, huh?\r\n";

    // Set up libcurl options
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_USERNAME, username.c_str());
    curl_easy_setopt(curl, CURLOPT_PASSWORD, password.c_str());
    curl_easy_setopt(curl, CURLOPT_MAIL_FROM, mail_from.c_str());

    struct curl_slist *recipients = nullptr;
    recipients = curl_slist_append(recipients, mail_rcpt.c_str());
    curl_easy_setopt(curl, CURLOPT_MAIL_RCPT, recipients);

    // Set up STARTTLS
    curl_easy_setopt(curl, CURLOPT_USE_SSL, CURLUSESSL_ALL);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 1L);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 2L);
    curl_easy_setopt(curl, CURLOPT_USE_TLS, CURLUSESSL_TRY); // Use STARTTLS

    // Set up the email data as the read data for CURLOPT_READFUNCTION
    curl_easy_setopt(curl, CURLOPT_READFUNCTION, read_data_callback);
    curl_easy_setopt(curl, CURLOPT_READDATA, &email_data);

    // Send the email
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        std::cerr << "Failed to send the email. Error: " << curl_easy_strerror(res) << std::endl;
    } else {
        std::cout << "Email sent successfully." << std::endl;
    }

    // Clean up
    curl_slist_free_all(recipients);
    curl_easy_cleanup(curl);
    return 0;
}
